package com.ohadsam.specialevents.calendar

import java.time.LocalDate
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Compares the calendar code with files generated by the independent library `pyluach` (tools/gen_golden.py).
 * Failures are collected so one run shows the pattern, not just the first mismatch.
 */
class GoldenCalendarTest {
    private fun lines(name: String): List<String> =
        checkNotNull(javaClass.getResourceAsStream("/golden/$name")) { "missing golden file $name" }
            .bufferedReader().use { it.readLines() }.filter { it.isNotBlank() }

    private fun assertNoFailures(what: String, failures: List<String>) =
        assertTrue("$what: ${failures.size} mismatches, e.g.\n" + failures.take(MAX_SHOWN).joinToString("\n"), failures.isEmpty())

    @Test
    fun gregorianToHebrewMatchesReference() {
        val failures = ArrayList<String>()
        for (line in lines("hebrew_dates.csv")) {
            val p = line.split(',')
            val expected = HebrewDate(p[1].toInt(), p[2].toInt(), p[3].toInt())
            val actual = HebrewCalendar.fromLocalDate(LocalDate.parse(p[0]))
            if (actual != expected) failures.add("${p[0]} expected $expected got $actual")
        }
        assertNoFailures("hebrew dates", failures)
    }

    @Test
    fun weeklyParshaMatchesReferenceForIsraelAndDiaspora() {
        val failures = ArrayList<String>()
        for (line in lines("parsha.csv")) {
            val p = line.split(',')
            val expected = if (p[2].isEmpty()) null else p[2].split(';').map(String::toInt)
            val actual = Parsha.ofShabbat(LocalDate.parse(p[0]), inIsrael = p[1] == "1")
            if (actual != expected) failures.add("${p[0]} il=${p[1]} expected $expected got $actual")
        }
        assertNoFailures("parsha", failures)
    }

    @Test
    fun festivalsAndFastsMatchReference() {
        val expected = HashMap<String, Set<String>>()
        for (line in lines("marks.csv")) {
            val p = line.split(',')
            expected["${p[0]},${p[1]}"] = p[2].split(';').toSet()
        }
        val failures = ArrayList<String>()
        var day = LocalDate.of(2000, 1, 1)
        val end = LocalDate.of(2060, 1, 1)
        while (day < end) {
            for (il in 0..1) {
                val actual = JewishCalendar.marksOn(day, inIsrael = il == 1).map { it.kind }.filter { it != MarkKind.ROSH_CHODESH }.map { it.name }.toSet()
                val want = expected["$day,$il"] ?: emptySet()
                if (actual != want) failures.add("$day il=$il expected $want got $actual")
            }
            day = day.plusDays(1)
        }
        assertNoFailures("marks", failures)
    }

    private companion object {
        const val MAX_SHOWN = 15
    }
}
